  "preferred_configuration": {
    "prize_parts": [
      {
        "ballot_id": "B050",
        "laureates": [
          "Michele Parrinello",
          "Roberto Car"
        ],
        "citation": "For the Car–Parrinello method joining first-principles electronic structure and molecular dynamics."
      }
    ]
  },
  "alternatives": [
    "B006",
    "B003"
  ],
  "statement": {
    "case_for": "The Car–Parrinello method made it possible to simulate atomic motion while retaining a first-principles description of the electrons. That combination opened realistic computational studies of materials and chemical processes, and decades of use show its lasting scientific value. The contribution is unusually well defined and jointly attributable to Car and Parrinello.",
    "case_against": "The method is now part of a much broader computational toolkit, and its influence can be difficult to separate from later extensions and alternative approaches. A prize should recognize the foundational advance without implying that it remains the exclusive route to first-principles dynamics.",
    "responses": [
      {
        "member_id": "mehlig-bernhard",
        "point": "Mehlig describes the Car–Parrinello method as a foundational joining of electronic-structure calculations and molecular dynamics, while cautioning that later approaches mean it should not be presented as exclusive.",
        "response": "I agree with both parts of that assessment. The later development of other methods does not diminish the historical importance of making this combination practical; it does make a narrowly phrased citation essential."
      },
      {
        "member_id": "lindroth-eva",
        "point": "Lindroth emphasizes that the quantum spin Hall effect established topological insulators as a new phase of matter through a strong prediction-and-experiment pairing, while noting the wider field has many contributors.",
        "response": "That is a compelling case, especially for the close connection between theory and measurement. I favor B050 because the credited joint contribution has a particularly clear boundary and its broad use over decades is directly tied to the original method."
      }
    ],
    "uncertainties": [
      "The historical assessment should distinguish the original Car–Parrinello advance from later extensions and related first-principles simulation methods."
    ],
    "conflict_note": "None apparent from the supplied profile."
  }
}
